//! Cargo-driven `eventlog.exe` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The body is eventlog-rust; reactos-link builds the PE.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry) = match arch.as_str() {
        "x86" => ("i686-kernel.json", "_wmainCRTStartup"),
        "x86_64" => ("x86_64-pc-windows-gnu", "wmainCRTStartup"),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "wmainCRTStartup"),
        o => panic!("eventlog-cargo: unsupported arch {o}"),
    };

    let late_libs: &[&str] = match arch.as_str() {
        "x86" => &["sdk/lib/pseh/libpseh.a", "sdk/lib/evtlib/libevtlib.a", "sdk/lib/crt/libchkstk.a", "sdk/lib/evtlib/libevtlib_rust.a", "sdk/lib/crt/CMakeFiles/oldnames.dir/oldnames.a"],
        "x86_64" => &["sdk/lib/pseh/libpseh.a", "sdk/lib/evtlib/libevtlib.a", "sdk/lib/evtlib/libevtlib_rust.a", "sdk/lib/crt/CMakeFiles/oldnames.dir/oldnames.a"],
        "aarch64" => &["sdk/lib/pseh/libpseh.a", "sdk/lib/evtlib/libevtlib.a", "sdk/lib/crt/libchkstk.a", "sdk/lib/evtlib/libevtlib_rust.a", "sdk/lib/crt/CMakeFiles/oldnames.dir/oldnames.a"],
        _ => unreachable!(),
    };

    Linker::new(target_json)
        .rust_staticlib("eventlog-rust")
        .c_from_compile_db("eventlog_shims", &["base/services/eventlog/eventlogrpc_s.c"])
        .resource_from_rc("base/services/eventlog/eventlog.rc", "eventlog_res")
        .import_lib("dll/win32/advapi32/advapi32.spec", "advapi32.dll", "advapi32")
        .import_lib("dll/win32/rpcrt4/rpcrt4.spec", "rpcrt4.dll", "rpcrt4")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // ...and those cmake linked after the body, in the same order.
        .static_libs_after_body(late_libs)
        .msvcrtex_crt(MsvcrtexKind::ExeWide)
        .link(ModuleKind::Win32Exe {
            entry: entry.into(),
            subsystem: "console:5.01".into(),
        });
}
